) VALUES (
  'b8adb4bd-fa13-5dcd-89a1-45ef86f44e88',
  'mf-st-gaudens-rassemblement-contre-le-racisme-20261026-trappes',
  'St-Gaudens - RASSEMBLEMENT CONTRE LE RACISME',
  'RASSEMBLEMENT CONTRE LE RACISME L''horreur qui s''est passée à Trappes nous concerne toutes et tous. On ne peut pas regarder cette violence comme un événement de plus. Depuis des années, le débat public se durcit. Le racisme et l''islamophobie occupent une place croissante dans l''espace médiatique, politique et social. Des discours qui auraient dû susciter une opposition ferme sont désormais présentés comme des opinions parmi d''autres. À force de désigner les mêmes populations comme des problèmes, des menaces ou des responsables de tous les maux, on finit par rendre acceptable ce qui ne devrait jamais l''être. C''est précisément contre cette banalisation que nous devons nous mobiliser. Car les mots ont un poids, les discours ont une portée et la manière dont une société regarde une partie de sa population dit quelque chose de ce qu''elle est prête à accepter. Nous refusons cette résignation. N',
  'droits',
  'Trappes',
  '78190',
  'FR', 'Europe/Paris',
  'Trappes',
  48.778249, 1.993009, NULL,
  '2026-10-26T14:00:00Z'::timestamptz,
  '2026-10-26T17:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.manifs.fr/2026-10-26-st-gaudens-rassemblement-contre-le-racisme-1869',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
  id, slug, title, description, category, city_name, postal_code, country_code, timezone,
