  is_demo, published_at, created_at, updated_at
) VALUES (
  'e256daaa-c189-59b5-a419-d2be5e77ad7e',
  'mf-nancy-appel-a-rassemblement-contre-le-racisme-20261026-trappes',
  '[Nancy] Appel à rassemblement contre le racisme',
  'Ce vendredi 23 octobre 2026, un attentat raciste était perpétré à Trappes et La Verrière, coûtant la vie à Pengo, jeune homme de 26 ans, et faisant plusieurs blessé·es graves dont une fillette de 12 ans touchée par 8 balles. Nous exprimons toute notre solidarité avec les victimes, leurs familles et les habitant·es des quartiers touché·es par cette attaque. Cet attentat intervient dans un contexte de banalisation et d''intensification des discours racistes, islamophobes et xénophobes dans le débat public. En désignant systématiquement les "étrangers" ou supposés étrangers comme des ennemis et des menaces, les partis politiques d''extrême droite et toutes celles et ceux qui relayent leurs idées nauséabondes et mortifères portent une responsabilité politique et médiatique directe et écrasante dans la banalisation des discours racistes et islamophobes. À l''approche de l''élection présidentielle',
  'droits',
  'Trappes',
  '78190',
  'FR', 'Europe/Paris',
  'Trappes',
  48.778249, 1.993009, NULL,
  '2026-10-26T14:00:00Z'::timestamptz,
  '2026-10-26T17:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.manifs.fr/2026-10-26-nancy-appel-a-rassemblement-contre-le-racisme-1892',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
