) VALUES (
  '9ccf20a5-ef7c-54d1-abe3-b51bf70ea5c1',
  'mf-hommage-aux-victimes-des-attentats-racistes-20261026-trappes',
  'HOMMAGE aux victimes des attentats racistes',
  'HOMMAGE aux victimes des attentats racistes[b][b]Montargis sp - sous-préfecture (lundi, 26 octobre 18:00) Montargis : rassemblement contre le racisme À la suite de l''attentat terroriste raciste survenu à Trappes A l''appel du MRAP ( https://mrap.fr/ ) et du Collectif Immigrés du Montargois Ce rassemblement sera un moment de recueillement, d''unité et de mobilisation citoyenne, pour dire non à la violence raciste et réaffirmer collectivement notre attachement aux valeurs de solidarité et de fraternité. Combien de minutes de silence encore ? Ne restons plus silencieux. Venez nombreuses et nombreux et partagez largement cette publication autour de vous. https://www.facebook.com/reel/1022272390886523 1 minute de silence à l''Assemblée Nationale ? LEURS DISCOURS DE HAINE TUENT. Idées slogans : Le RN tue - La haine tue - Oui/Le racisme tue - Repose en paix Pengo Bossio Wangi 2000-2026 - Colère, l',
  'droits',
  'Trappes',
  '78190',
  'FR', 'Europe/Paris',
  'Trappes',
  48.778249, 1.993009, NULL,
  '2026-10-26T14:00:00Z'::timestamptz,
  '2026-10-26T17:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.manifs.fr/2026-10-26-hommage-aux-victimes-des-attentats-racistes-1885',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
