  'mf-rennes-rassemblement-en-hommage-aux-victimes-de-l-attentat-raciste-de--20261026-trappes',
  'Rennes - Rassemblement En hommage aux victimes de l''attentat raciste de Trappes et la Verriere',
  'Rassemblement En hommage aux victimes de l''attentat raciste de Trappes et la Verriere Rassemblement en hommage aux victimes de l''attentat raciste islamophobe et négrophobe de Trappes et la Verriere Rassemblement ce lundi 27/10 à 18h à la Halle Agnes Tirop, métro Blones Suite à l''attentat raciste, islamophobe et négrophobe du 23 octobre à Trappes. En mémoire de Pengo Bossio Wangi, en soutien aux blessé.e.s et aux familles des victimes. Retrouvons nous pour un moment de recueillement et pour demander justice. A Rennes, comme dans le reste de la France, les agressions racistes se multiplient. Régine Komokoli, conseillère municipale de la France insoumise a vu sa voiture dégradée et a reçu de nombreuses menaces de mort. Des militants fascistes s''attaquent aux manifestants du 24 octobre. Des mosquées rennaises ont été dégradées. La mairie, la préfecture et leurs polices font la chasse aux per',
