  '#Dunkerque - Rassemblement contre le racisme et l''islamophobie',
  'RASSEMBLEMENT contre le racisme et l''islamophobie ANNONCE DE RASSEMBLEMENT LUNDI 26 à 18:00 COMMUNIQUÉ DE PRESSE Assemblée des quartiers 31 Toulouse, le 25 octobre 2026 Rassemblement contre le racisme et l''islamophobie Lundi 26 octobre à 18 h - Métro Jean-Jaurès, Toulouse L''horreur qui s''est passée à Trappes nous concerne toutes et tous. On ne peut pas regarder cette violence comme un événement de plus. Depuis des années, le débat public se durcit. Le racisme et l''islamophobie occupent une place croissante dans l''espace médiatique, politique et social. Des discours qui auraient dû susciter une opposition ferme sont désormais présentés comme des opinions parmi d''autres. À force de désigner les mêmes populations comme des problèmes, des menaces ou des responsables de tous les maux, on finit par rendre acceptable ce qui ne devrait jamais l''être. C''est précisément contre cette banalisation q',
