  'Laragne - Attentat raciste à Trappes rassemblement citoyens',
  'Attentat raciste à Trappes rassemblement citoyens En soutien aux victimes de l''attentat racise à Trapes et contre la banalisation de la Haine raciste. Appel à rassemblement, ce lundi 26 octobre à 18h sur la place de la fontaine à Laragne avec pancartes, bougies, flambeaux et lampions. Ce vendredi 23 octobre 2026, un attentat raciste était perpétré à Trappes et La Verrière, coutant la vie à Pengo, jeune homme de 26 ans et espoir du mma, et faisant plusieurs blessés graves dont une fillette de 12 ans. Face à l''horreur, en soutien aux victimes et pour dénoncer la banalisation de la haine raciste, la LDH, SOS racisme, le Mrap, ADDAM, Clara Jalons pour la paix, FIDL, UNEF, CGT, CFDT, FSU, Union Syndicale Solidaires, UNSA et d''autres organisations de la société civile appellent à un large rasseblement ce lundi 26 oct 2026 partout en France. Nous, habitant.e.s du Buêch nous associons à cet appe',
