  'Roubaix - Rassemblement en hommage aux victimes de l''attentat raciste de Trappes',
  'Rassemblement en hommage aux victimes de l''attentat raciste de Trappes La LDH de Lille appelle à se joindre au rassemblement à Roubaix avec la section LDH Roubaix-Tourcoing-Vallée de la Lys. Roubaix, ville monde forgée par la richesse de l''immigration, de l''interculturalité, d''une diversité qui est une fierté et une force! C''est donc sur la grand place de Roubaix que nous souhaitons rendre hommage aux victimes de cet attentat islamophobe et raciste, qui doit permettre à chacune et chacun de prendre conscience que les paroles de haine qui désignent des populations à la vindicte conduisent aux actes les plus violents. 📍18h lundi 26 octobre - Grand Place de Roubaix',
