  'Cazères - RASSEMBLEMENT CONTRE LE RACISME',
  'APPEL A RASSEMBLEMENT DEMAIN A CAZERES !Lundi 26 octobre - 18h - Parvis de l''Hôtel de Ville En hommage et soutien aux victimes, et réaction à l''attentat raciste qui s''est passé à Trappes et qui nous concerne toustes. Nous relayons l''appel des organisations et collectifs antiracistes à se rassembler à 18h dans tout le pays. Des cazerien·nes "L''horreur qui s''est passée à Trappes nous concerne toutes et tous. On ne peut pas regarder cette violence comme un événement de plus. Depuis des années, le débat public se durcit. Le racisme et l''islamophobie occupent une place croissante dans l''espace médiatique, politique et social. Des discours qui auraient dû susciter une opposition ferme sont désormais présentés comme des opinions parmi d''autres. À force de désigner les mêmes populations comme des problèmes, des menaces ou des responsables de tous les maux, on finit par rendre acceptable ce qui n',
