  '274b768c-4aa6-596b-89f4-165c06c79a26',
  'mf-hommage-aux-victimes-de-l-attentat-raciste-islamophobe-et-negrophobe-d-20261026-montpel',
  'Hommage aux victimes de l''attentat raciste islamophobe et négrophobe de Trappes & La Verrière',
  'Hommage aux victimes de l''attentat raciste islamophobe et négrophobe de Trappes & La Verrière[b][b]Plan Cabanes (Montpellier) - Plan Cabanes (lundi, 26 octobre 18:00) RDV PARTOUT EN FRANCE LUNDI 26 À 18 H À Montpellier Plan Cabanes Après la tuerie raciste, négrophobe et islamophobe de Trappes et La Verrière, après la mort de Pengo Bossio Wangi, 26 ans, et les blessés, dont une fillette de 12 ans, nous nous rassemblons le même jour à la même heure partout en France, à l''appel de collectifs, associations impliquées depuis toujours contre le racisme. Tout d''abord pour rendre un hommage aux victimes, affirmer notre solidarité aux familles endeuillées, aux blessé.e.s et à leurs proches. Nous exigeons que la justice soit faite et condamnons la chaîne des responsabilités. Ce qui s''est passé n''est pas un drame isolé, c''est une fois de plus l''aboutissement politique du racisme avec ses relais méd',
