  'cae235c6-7bec-562b-9cd6-57b2c9bab474',
  'mf-rassemblement-pour-tous-tes-les-prisonnier-es-du-mouvement-social-20261027-lyon',
  'Rassemblement pour tous-tes les prisonnier-es du mouvement social !',
  'Hier comme pendant toutes les autres journées de mobilisation du mouvement social, des dizaines de personnes ont encore été interpellées. Alors que des personnes ont déjà été envoyées en prison, il est urgent de construire la solidarité et les soutenir ! Pour ça, rassemblons nous lundi et mardi toute l''après-midi devant le tribunal à partir de 13h30 ! Hier, plus de 1000 personnes ont encore été interpellées sur l''ensemble du territoires et plus d''une trentaine sur Lyon seulement. Comme la semaine précédente, l''Etat va chercher à faire appliquer des peines très lourdes pour effrayer le mouvement. Il est urgent de nous mobiliser et de construire la solidarité pour les soutenir face à la vengeance de la justice. Pour exiger la libération de toutes les personnes interpellées ces deux derniers samedis mais aussi depuis le début du mouvement lycéen. Et pour ne pas laisser la justice condamné à',
  'droits',
  'Lyon',
  '69001',
  'FR', 'Europe/Paris',
  'Lyon',
  45.758, 4.835, NULL,
