  'mf-nice-appel-a-un-grand-rassemblement-unitaire-20261027-nice',
  'Nice - Appel à un grand rassemblement unitaire',
  'Appel à un grand rassemblement unitaire LE BRUIT DES BOTTES Interdire les manifestations du 24 octobre, trier les colères légitimes et décider qui a le droit de s''exprimer : voilà où nous mène la fuite en avant autoritaire et liberticide du pouvoir ! Le droit de manifester, droit constitutionnellement protégé, n''est ni une faveur du préfet ni un privilège accordé aux mobilisations qui plaisent au gouvernement. C''est un pilier de notre démocratie, et nous ne laisserons personne le piétiner. Par ailleurs, les images glaçantes de l''ultra-droite niçoise semant la terreur en tout impunité dans les rues de Nice ce samedi obligent une réaction sans faille. Aujourd''hui, nous appelons à un sursaut collectif ! Associations, syndicats, organisations politiques, collectifs, citoyen-es, artistes, salarié·es, précaires, lycéen-es, étudiant-es, défenseuses et défenseurs des droits: toutes celles et tou',
