  '05692998-0e0a-5902-ba29-6d02b755bd44',
  'mf-hommage-aux-victimes-des-attentats-racistes-20261027-orleans',
  'HOMMAGE aux victimes des attentats racistes',
  'HOMMAGE aux victimes des attentats racistes[b][b]Orléans r - Place de la République (mardi, 27 octobre 19:00) RASSEMBLEMENT CITOYEN À ORLÉANS en hommage aux victimes de l''attentat raciste, islamophobe et négrophobe de Trappes & La Verrière et pour dénoncer la banalisation de la haine raciste. À la suite de l''attentat terroriste raciste survenu à Trappes, Élan Citoyen Orléanais (ECO) organise un rassemblement citoyen et pacifique en hommage aux victimes. Nous invitons toutes celles et ceux qui le souhaitent à nous rejoindre pour exprimer leur soutien aux victimes, à leurs familles et à leurs proches. Ce rassemblement sera un moment de recueillement, d''unité et de mobilisation citoyenne, pour dire non à la violence raciste et réaffirmer collectivement notre attachement aux valeurs de solidarité et de fraternité. Combien de minutes de silence encore ? Ne restons plus silencieux. Venez nombr',
