  'Rassemblement contre les crimes racistes',
  '« Ce 23 octobre 2026 à Trappes et à La Verrière, la haine raciste a tué un jeune homme, Pengo Bossio Wangi de 26 ans, parce que noir, et blessé gravement cinq personnes au total dont une enfant de douze ans en urgence absolue ; toutes les victimes ont été ciblées à partir leur apparence et d''une assignation nourrie de xénophobie et de racisme islamophobe. » [b]Face à l''horreur raciste, mobilisons-nous[b][b]Rassemblement à Dijon place de la Liberation[b][b]Mardi 27 octobre 17h30[b]--------- Ce 23 octobre 2026 à Trappes et à La Verrière, la haine raciste a tué un jeune homme, Pengo Bossio Wangi de 26 ans, parce que noir, et blessé gravement cinq personnes au total dont une enfant de douze ans en urgence absolue ; toutes les victimes ont été ciblées à partir leur apparence et d''une assignation nourrie de xénophobie et de racisme islamophobe, c''est pourquoi le parquet national antiterroriste',
