  'mf-soutien-pour-l-audience-en-correctionnelle-pour-avoir-soutenu-la-pales-20261028-paris',
  'Soutien pour l''audience en correctionnelle pour avoir soutenu la Palestine',
  'Nous relayons plusieurs appels à soutiens : 📣 Le premier concerne des camarades interpellé.es hier midi et actuellement en GAV dans le commissariat central de Paris (Rue Vicaire) . Rejoignez leurs proches dès aujourd''hui devant le commissariat à partir de 11h30 📣 Le second est dans la continuité des nombreux passages en comparution immédiate qui ont suivi les mobilisations du 17 et 18 octobre. Certain.e.s camarades jugé.es le jour même ont subi des peines de prison ferme avec mandat de dépôt (envoyé.e.s directement en prison). D''autres ont demandé un délai pour préparer leur défense et se sont retrouvé.e.s en détention provisoire. Ce lundi à 13h30 au tribunal judiciaire de Paris (porte de clichy) a lieu le procès de Demande de Mise en Liberté de 3 d''entre elleux. Il aura lieu dans la section 23.1 du tribunal, la salle sera affichée sur les écrans dans le hall d''entrée. Nous appelons à êt',
