  '1cf8f5b0-1c70-5d8d-a7b0-34797d246e30',
  'mf-rennes-travailleurs-travailleuses-construisons-le-mouvement-construiso-20261028-rennes',
  'Rennes - Travailleurs + travailleuses ! Construisons le mouvement + construisons la grève !',
  'Travailleurs, travailleuses ! Construisons le mouvement, construisons la grève ! Le capitalisme en crise n''a aucune réponse à apporter à la colère de la jeunesse et des travailleurs et travailleuses en révolte contre ce monde injuste. Pour s''accaparer les ressources, étendre son influence et relancer son économie, il fait le choix de la guerre. En Ukraine ou en Iran, ces guerres sont les prémices d''une préparation plus générale à la troisième guerre mondiale. Partout, les budgets militaires augmentent, au détriment de la santé, de l''éducation et des services publics. La jeunesse a conscience que le capitalisme n''a rien à lui offrir pour son avenir. Depuis septembre, le mouvement lycéen est venu secouer le pouvoir, tant par sa massivité que par sa composition et sa détermination. Ce mouvement a largement contribué à construire un 17 octobre massif et déterminé, historique à bien des égard',
  'social',
