  'mf-cinema-militant-lyd-20261028-montpellier',
  'Cinéma militant "Lyd"',
  'Cinéma militant "Lyd"[b][b]Cinéma Utopia (Montpellier) - 5, avenue du Docteur Pezet (mercredi, 28 octobre 20:00) Lyd est un documentaire de science-fiction qui retrace l''ascension et la chute de Lyd, une métropole palestinienne sous occupation israélienne depuis 1948. Mélangeant images d''archives et séquences d''animations, le film rapporte les faits historiques de la Nakba, tout en imaginant un monde parallèle sans l''avènement de la colonisation sur cette ville et sa population exilée. Établie aux alentours de 5600 avant JC, la cité de Lyd se classait parmi les plus vastes et anciennes villes de Palestine avant qu''elle ne soit occupée par Israël. La majorité des résidents palestiniens de la région ont été expulsés en 1948, menant à des tueries qui demeurent largement méconnues. La perspective palestinienne sur Lyd ayant été écartée des archives publiques, ce magnifique film propose un co',
  'droits',
  'Montpellier',
  '34000',
  'FR', 'Europe/Paris',
  'Montpellier',
