  'bb977611-f6b2-5db5-a18a-eafe016d273d',
  'mf-limoges-evenement-de-solidarite-avec-les-anarchistes-incarcere-es-en-i-20261029-clermon',
  'Limoges - Evénement de solidarité avec les anarchistes incarcéré-es en Indonésie',
  'Événement de solidarité avec les anarchistes incarcéré-es en Indonésie Depuis les révoltes de l''été 2025, les compagnon-nes d''Indonésie subissent une vague de représsion. Plusieurs centaines de personnes ont été incarcérées. Des collectifs sur place essaient de soutenir ces personnes et de continuer à lutter malgré ces coups durs. Nous avons eu envie de les soutenir nous aussi et d''informer sur la situation actuelle en Indonésie. Cet événément s''inscrit dans une série d''événements similaires tout au long du mois d''octobre dans différentes villes en France : à Besançon, à Paris ou encore à Clermont-Ferrand. Au programme de la soirée : une cantine à prix libre organisée par la Dahl, la projection d''un film, un infokiosque sur les luttes et l''anarchisme en Indonésie et sur la phase de répression actuelle, des discussions, et peut-être même une super playlist de punk si l''ambiance s''y prête',
  'droits',
  'Clermont-Ferrand',
  '63000',
  'FR', 'Europe/Paris',
  'Clermont-Ferrand',
  45.786671, 3.107055, NULL,
  '2026-10-29T14:00:00Z'::timestamptz,
  '2026-10-29T17:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.manifs.fr/2026-10-29-limoges-evenement-de-solidarite-avec-les-anarchistes-incarcere-es-en-indonesie-1497',
