  'e0695213-6e19-53cc-b755-2774f8d63e31',
  'mf-centre-cercles-de-silence-protestation-silencieuse-contre-les-politiqu-20261030-strasbo',
  'Centre - Cercles de silence - Protestation silencieuse contre les politiques migratoires',
  'Cercles de silence - Protestation silencieuse contre les politiques migratoires Cette interpellation a lieu chaque mois dans environ, 150 villes de France, et depuis 2008 à Strasbourg, le cercle de silence moment de protestation silencieuse. Pour dire non à l''enfermement en rétention, aux renvois violents d''étrangers, aux morts aux frontières et en mer. Pour marquer notre refus des traitements inhumains et dégradants que subissent des hommes, femmes et enfants sur le territoire français, du simple fait qu''ils n''arrivent pas à faire reconnaître leurs droits. Avec le temps, on constate une grande baisse de participation, certains cercles s''arrêtent... A Strasbourg, malgré la baisse de participation, nous ne pouvons nous résoudre à arrêter, dans un moment politique où la lutte contre « le désordre migratoire » est une priorité du Ministre de l''Intérieur et où la refonte en cours de la Direc',
  'autre',
