  'mf-figeac-defendons-notre-droit-de-manifester-et-notre-droit-a-vivre-dign-20261031-figeac',
  'Figeac - Défendons notre droit de manifester, et notre droit à vivre dignement !',
  'Défendons notre droit de manifester, et notre droit à vivre dignement. Samedi 31 octobre 2026 à Figeac, Manifestation déclarée RDV à 10h aux jardins de l''hôpital, avec atelier pancarte, repas partagé à midi aux jardins de l''hôpital et AG à 13h30. 10 h - Manifestation à Figeac , RDV à 10h aux jardins de l''hôpital thème d''Halloween ou del Día de los Muertos proposé. 12 h - Repas partagé aux jardins de l''hôpital. Vers 13 h 30 - Assemblée générale au même endroit.',
