  '69b403d4-c229-5fba-bec4-324a6de22412',
  'mf-nimes-afps-avec-le-peuple-palestinien-pour-saluer-le-mouvement-de-grev-20261031-nimes',
  'Nîmes - AFPS - AVEC LE PEUPLE PALESTINIEN POUR SALUER LE MOUVEMENT DE GRÈVE DES ...',
  'AFPS - AVEC LE PEUPLE PALESTINIEN POUR SALUER LE MOUVEMENT DE GRÈVE DES ... SAMEDI 31 OCTOBRE DE 11 h à 13 h AVENUE FEUCHÈRES RASSEMBLEMENT DE SOLIDARITÉ AVEC LE PEUPLE PALESTINIEN ET POUR SALUER LE MOUVEMENT DE GRÈVE DES DOCKERS DU 30 OCTOBRE CONTRE LA GUERRE ! À noter qu''une seconde édition de la journée internationale menée par les dockers, aura lieu le vendredi 30 octobre 2026 sous le mot d''ordre « Les dockers ne travaillent pas pour la guerre ». Des syndicats et collectifs d''ouvriers portuaires de près de 100 ports, répartis dans 17 pays (en Europe, Asie, Afrique et Amériques), préparent des grèves, des blocages et des rassemblements pour dénoncer la militarisation croissante, l''économie de guerre, et exiger l''arrêt du transport d''armes, de munitions et de marchandises liées aux conflits en cours, notamment vers Israël.',
  'droits',
  'Nîmes',
  '30000',
  'FR', 'Europe/Paris',
  'Nîmes',
  43.814652, 4.356289, NULL,
