  'd8449221-3d24-52b7-9c67-7f1586eb9677',
  'ami-reunion-publique-soutien-au-peuple-palestinien-20261031-paris',
  'Réunion publique, soutien au peuple palestinien',
  'L''Afps Paris-Sud et le Collectif Unitaire de soutien au peuple palestinien appellent à une réunion publique le samedi 31 octobre 2026 à 14h00 à la Maison de la Vie Associative et Citoyenne 13e - 31 rue Bobillot - Paris 13e pour développer du thème ci-après : – Post-octobre 2023 : la question palestinienne à l''épreuve des guerres régionales – Quel devenir pour la Palestine, le Liban, la Syrie, l''Iran... pays menacés par l''expansionnisme israélien et l''impérialisme états-unien ? 350',
