  '0b40ea31-88cb-5411-bfb9-f4d4418fc8f9',
  'mf-rassemblement-pour-une-paix-juste-et-durable-en-palestine-20261031-paris',
  'Rassemblement pour une paix juste et durable en Palestine',
  'Rassemblement pour une paix juste et durable entre Palestiniens et Israéliens, tous les samedis à 15h place Darcy ! Rassemblement samedi 20 juin[b]Comme tous les samedis, rassemblons-nous à 15h place Darcy en soutien à la Palestine. [b]Veillée à la bougie[b]Le samedi 8 Novembre, après la manifestation, se tiendra une veillée place de la Libration : apporter bougies et photophores.. [b]Veillée à la bougie[b]Le samedi 8 Novembre, après la manifestation, se tiendra une veillée place de la Libration : apporter bougies et photophores.. [b]Assemblée dynamique le 13 septembre[b]Le samedi 13 septembre, le Collectif 21 pour une paix juste et durable en Palestine organise son rassemblement place Darcy à 15h sous forme d''une AG dynamique : venez apporter vos idées, vos propositions d''actions. Cela permettra de dynamiser notre soutien aux palestinien·nes, la dénonciation des complices du génocide, e',
