  'bd09ab50-d426-5709-8930-ae7981aaa6cd',
  'ami-club-de-lecture-queer-et-feministe-tws-20261103-paris',
  'Club de lecture queer et féministe (TWS)',
  'L''association The Witches'' Society propose son club de lecture queer et féministe le mardi 3 novembre 2026, de 18h30 à 20h30, à la Maison de la Vie Associative et Citoyenne du 13e arrondissement, 31, rue Bobillot, Paris 13e, près de la place d''Italie. Au programme : une heure de lecture en silence (Silent Book Club), suivie d''une heure d''échanges autour des lectures personnelles et des idées de chacun·e. Un rendez-vous mensuel pour partager des perspectives queer et féministes et se retrouver autour des livres. Participation gratuite. Inscription ici Voir aussi The Witches'' Society Voir aussi Paris.fr 350',
  'droits',
  'Paris',
