) VALUES (
  'd45d0e4d-886c-524f-812d-07c085255cd5',
  'mf-manifestation-pour-les-crevettes-20261104-paris',
  'Manifestation pour les crevettes',
  'Quand ? Le 4 novembre à 11h Où ? siège de Lidl 35 Avenue Sully Prudhomme, 92290, Châtenay-Malabry, France Environ 440 milliards de crevettes sont tuées chaque année dans des élevages, soit près de 14 000 chaque seconde. Beaucoup de crevettes meurent asphyxiées hors de l''eau ou plongées vivantes dans un bain d''eau glacée. Pour des animaux capables de ressentir la douleur, ce sont des pratiques d''une grande cruauté. Mais leur souffrance est soigneusement invisibilisée par l''industrie, et presque personne n''a conscience des horreurs qu''on leur fait subir. On demande aux chaînes de supermarchés de cesser de vendre des crevettes mortes par suffocation et d''imposer l''étourdissement électrique avant abattage. Partout en Europe, des collectifs se battent pour pousser Lidl à mettre fin à ces pratiques. La France rejoint le mouvement ! Le 4 novembre, on se rend devant le siège de Lidl pour porter',
  'autre',
  'Paris',
  '75001',
  'FR', 'Europe/Paris',
  'Paris',
  48.859, 2.347, NULL,
  '2026-11-04T10:00:00Z'::timestamptz,
