  'mf-rassemblement-devant-le-forum-des-entreprises-de-l-armement-de-phelma-20261105-paris',
  'Rassemblement devant le forum des entreprises (de l''armement) de Phelma',
  'Salut les camarades 📣, C''est encore le collectif SIAG (Stop à un INP qui Alimente les Guerres) 🦔 C''est toujours la saison des forums des ingénieur.es génocidaires ! Et le 5 novembre c''est un jour de double forum : - le forum de Phelma toute la journée (présence de Lynred, ST Micro, MBDA (Ha non on les as viré définitivement l''année dernière), ...) - et le forum de GI l''après-midi (présence de Caterpillar, le groupe Bolloré, Thalès, ...) Après avoir bloqué toustes ensemble (ça a bien mis la pression à l''admin) et empuanti* le forum de l''Ensimag le 15 octobre, rendez-vous le 📌 jeudi 5 novembre dès 7h45 sur le parvis Louis Néel 📌 (devant le bâtiment Minatec). N''hésitez pas à venir avec vos meilleurs slogans et votre déter ! A vite et bon courage pour les luttes :) Free Palestine, Free Kanaky, Free Sudan, Free Congo ! 🦔 Le collectif SIAG *empuantir : remplir un lieu ou gêner quelqu''un par un',
