  'Quelques rendez-vous des prochaines semaines ! 25 septembre, 8h : Procès de militant.es d''XR, au Tribunal Judiciaire d''Angers 26 septembre, 14h : Manifestation pour la paix et le climat, Place du Ralliement 26-27 septembre : Festival RuralEs et LibrEs, Un Pas De Côté à Saint Lézin 29 septembre, 15h : Manifestation services publiques, place du Ralliement 29 septembre, 18h : AG antifasciste, parvis du théâtre du Quai 3 octobre, 12h : Manifestation et pique-nique anti canons français, à Chemillé 3-4 octobre : Banquet Tables Ouvertes, La Grande Noé, Valanjou',
