  '134c3893-3d25-5db2-8771-0224429e68fa',
  'mf-manifestation-intersyndicale-20261105-orleans',
  'MANIFESTATION intersyndicale',
  'MANIFESTATION intersyndicale[b][b]Orléans - Place De Gaulle (jeudi, 5 novembre 00:00) Pour les salaires, les services publics, l''emploi et l''industrie Juste après le vote du projet de budget pour 2027, qui prévoit de nombreuses mesures d‘économies et de gels des évolutions de prestations malgré l''inflation, les syndicats réclament des augmentations de salaires, des pensions de retraite, du point d''indice des fonctionnaires, du Smic et des aides sociales. Ils dénoncent “un déclassement inédit” de ceux qui travaillent. L''intersyndicale CFDT https://www.cfdt.fr/sinformer/communiques-de-presse/appel-a-la-mobilisation-pour-les-salaires-les-services-publics-l-emploi-et-l-industrie CGT https://www.cgt.fr/5nov FO https://www.force-ouvriere.fr/appel-a-la-mobilisation-pour-les-salaires-les-services-publics-l Unsa https://www.unsa.org/une-forte-mobilisation-et-des-violences-inacceptables/ FSU https',
  'social',
  'Orléans',
  '45000',
  'FR', 'Europe/Paris',
  'Orléans',
  47.873569, 1.911358, NULL,
  '2026-11-05T14:00:00Z'::timestamptz,
  '2026-11-05T17:00:00Z'::timestamptz,
  TRUE,
