  'd5768c94-a9a4-5699-8489-5ecc96744907',
  'mf-nice-greve-et-des-manifestations-interprofessionnelles-20261105-nice',
  'Nice - grève et des manifestations interprofessionnelles',
  'grève et des manifestations interprofessionnelles grève et des manifestations interprofessionnelles Une grève et des manifestations interprofessionnelles sont prévues le 5 novembre 2026. L''appel a été lancé le 5 octobre par l''intersyndicale . Il s''adresse aux salariés du public et du privé, aux retraités et aux jeunes. Les syndicats réclament des hausses de salaires, la défense des services publics, de l''emploi et de l''industrie. Ils dénoncent le projet de budget 2027 du gouvernement Lecornu, notamment le gel des prestations sociales. Cette journée fait suite à la mobilisation de la fonction publique du 29 septembre, qui a compté plus de 170 manifestations et environ 300 000 manifestants selon la presse. Elle se déroule alors que des blocus lycéens se poursuivent.',
  'social',
