  '49fc084a-ffe6-5687-9c4c-419314777c6c',
  'mf-danse-musique-chant-je-vous-ecris-de-gaza-par-la-cie-djamila-henni-che-20261106-paris',
  'Danse + musique + chant : “JE VOUS ÉCRIS DE GAZA“ par la Cie Djamila HENNI-CHEBRA',
  'La chorégraphe, Djamila HENNI-CHEBRA, sensibilisée au sort du peuple palestinien décide de lui dédier sa nouvelle création ### **Danse, musique, chant** **"JE VOUS ÉCRIS DE GAZA"** --------------------------- ### **par la Cie Djamila HENNI-CHEBRA** Un personnage fictif Zeine, interprété par une comédienne, invite le spectateur à découvrir une histoire, un peuple, une culture, la vie en Palestine depuis le début du XXe siècle, un siècle marqué par les drames et la douleur. De nombreux épisodes douloureux sont rappelés: Mandat Britannique 1920, la révolte arabe 1936, la Nakba 1948, et les multiples guerres 1967 guerre des six jours, 1973 guerre du Kippour... et jusqu''à ce terrible 7 Octobre 2023. Zeine pour qui tout n''a pas commencé le 7 octobre 2023 écrit de Gaza et s''adresse au monde, un monde qui semble avoir oublié Gaza. Cette création, en dépit des drames du peuple palestinien depuis',
  'droits',
