  'e8e55be7-9305-5b45-a11a-2281c428b544',
  'mf-cahors-invitation-au-rassemblement-de-solidarite-avec-le-peuple-palest-20261107-cahors',
  'Cahors - Invitation au rassemblement de solidarité avec le peuple palestinien',
  'Invitation au rassemblement de solidarité avec le peuple palestinien L''Association France Palestine Solidarité du Lot (AFPS 46) vous invite à un rassemblement en faveur du peuple palestinien. 📅 Samedi 7 novembre à 11 h 📍 Parvis de la mairie de Cahors Ce rassemblement portera notamment sur la situation à Gaza, le traité de libre-échange entre l''Union européenne et Israël, ainsi que les sanctions américaines visant la Cour pénale internationale. L''AFPS 46 organise un rassemblement chaque premier samedi du mois. N''hésitez pas à transmettre cette invitation autour de vous. Pour toute information : afpsex46@outloexok.com Solidairement, AFPS 46 - Cahors',
