  'mf-poitiers-manifestation-un-toit-est-un-droit-20261107-poitiers',
  'Poitiers - Manifestation Un toit est un droit',
  'Un toit est un droit Tous les soirs à Poitiers, des dizaines de personnes dorment à la rue. Qu''elles soient françaises ou immigrées, avec ou sans papiers. Qu''elles soient mineures ou majeures. Qu''elles soient célibataires ou en famille. Qu''elles soient en demande d''asile ou pas Pour que personne ne reste à la rue, soyons nombreuses et nombreux à nous mobiliser',
