  'bb65748f-1084-5156-9459-d1ec90740965',
  'mf-non-a-la-marche-aux-flambeaux-des-fascistes-du-grand-ouest-20261107-tours',
  'Non à la marche aux flambeaux des fascistes du grand Ouest !',
  'Le 7 novembre 2026 aura lieu à Tours une marche fasciste prétextant un hommage à Saint-Martin pour la 4ᵉ année consécutive, organisée par le groupuscule néofasciste Des Tours et Des Lys et rassemblant des figures d''extrême droite du grand ouest. Chaque année, c''est le bruit des bottes qui retentit une soirée entière à Tours, accompagné d''une violence débridée des fachos , qui en profitent pour se lâcher, en amont et en aval de la marche, en effrayant les habitant·es et en menant des rondes de surveillance contre les militant·es antifascistes allant jusqu''au tabassage en règle. Cette marche aux flambeaux a tout de la marche militaire : ils s''alignent, ils tendent le bras pour vérifier la distance entre les lignes (toute ressemblance avec un salut nazi serait fortuite), scandent des slogans nationalistes (“Notre fierté c''est notre identité”, “Saint Martin, revenez, la Touraine est en dange',
  'autre',
