  'Aprèm'' Antimilitariste',
  'Le Collectif contre la militarisation de la jeunesse vous invite le mercredi 11 novembre 2026 ! Événement Antimilitariste Prix libre (entrée / repas et boissons) ; prévoir du cash 14h-18h30 : Ateliers : – Éducation à la paix – Création graphique – Arpentage de la loi Blanchet – Lecture de livres jeunesse et discussion (pour différentes tranches d''âge) – Présentation de la Cartographie Armée-Jeunesse – Chorale – Jeux collectifs et collaboratifs – etc Goûter crêpes Table Ronde Avec intervenantes et discussion Repas avant ou après la table ronde Fin à 21h30 Ouvert à toustes, tous les âges Le lieu est accessible PMR Voir aussi sur Mastodon 350',
