  'ami-fete-des-10-ans-de-la-legal-team-paris-idf-20261114-montreuil',
  'Fête des 10 ans de la Legal Team Paris IDF',
  '10 ANS DE LEGAL TEAM PARIS : ON FÊTE ÇA ! La Legal Team Paris, issue de la coordination anti-répression IDF, fête ses 10 ans et vous donne rendez-vous le 14 novembre 2026, à la Parole Errante, Montreuil, de 14h à minuit. Notez la date, invitez vos amix et préparez-vous : on fête 10 ans de luttes, de solidarité et d''anti-répression... et on se prépare à la bagarre pour les 10 prochaines années ! L''après-midi : on s''entraîne et on s''outille ! Ateliers d''anti-répression, confection de cagoules, boxe, danse... de quoi apprendre, transmettre, bouger et se préparer collectivement. Le soir : place à la fête ! Des concerts pour tous les goûts, des DJ sets et de quoi danser jusqu''à minuit. Toute la journée et toute la soirée, la super équipe du Barcredi sera derrière le bar, avec et sans alcool. Et les Tabliers Volants nous régaleront de crêpes et autres mets délicieux, à prix libre. Et parce qu''',
