  'mf-manifestation-de-soutien-a-gaza-20261115-paris',
  'Manifestation de soutien à GAZA',
  'Le premier rendez-vous, le 6 novembre 2023, à l''appel d''un collectif d''associations, syndicats ou partis, toujours les mêmes depuis, avait rassemblé plus de 2700 personnes pour dénoncer un bilan de 9.500 morts dont 3.900 enfants, déjà, en représailles à la sanglante attaque du Hamas du 7 octobre qui avait fait 1.400 morts en Israël, effroyable comptabilité ! Les derniers bilans officiels des victimes palestiniennes dépassent en 2025 les 146.000 morts pour la plupart civiles dans le silence quasi général des Nations arabes et occidentales. Les rendez-vous de la Porte d''Aix, chaque dimanche à 14H, se poursuivront tant que ne cesseront pas massacres, famine et injustices sans nom en Palestine. Pour vérifier les rendez-vous hebdomadaires, voir le site : www.assopalestine13.org',
