  'ami-vernissage-photo-mais-est-ce-que-t-avais-dit-non-violences-sexistes-et-20261117-paris',
  'Vernissage photo ''Mais est-ce que t''avais dit non ?'' Violences sexistes et sexuelles',
  'À l''occasion des mobilisations du 25 novembre contre les violences faites aux femmes, The Witches'' Society vous invite au vernissage de l''exposition photo « Mais est-ce que t''avais dit non ? », consacrée à la victimisation secondaire. Après avoir subi des violences, certaines phrases entendues peuvent marquer durablement et constituer de nouvelles violences : paroles qui minimisent les faits, mettent en doute la parole ou font porter la culpabilité aux personnes qui les ont subies. À travers la photographie, cette exposition propose d''ouvrir le dialogue et de nourrir la lutte contre les violences sexistes et sexuelles (VSS). Les photographies sont accompagnées de créations réalisées lors d''ateliers d''art exutoire. Vernissage : mardi 17 novembre 2026, de 19 h à 20 h. Lieu : Maison de la Vie Associative et Citoyenne (MVAC) du 13e arrondissement, 31 rue Bobillot, 75013 Paris. L''exposition e',
