  '34c7eb42-1483-5ee2-b352-d5e630ec18f9',
  'mf-les-tisseurs-de-liens-proposent-desinformation-pourquoi-on-se-fait-tou-20261121-paris',
  '"Les Tisseurs de Liens" proposent : DÉSINFORMATION - POURQUOI ON SE FAIT TOUS AVOIR, COMMENT RIPOSTER ?',
  '"Les Tisseurs de Liens" proposent : DÉSINFORMATION - POURQUOI ON SE FAIT TOUS AVOIR, COMMENT RIPOSTER ?[b][b]LES SHEDS - KINGERSHEIM - 2A, rue d''Illzach (samedi, 21 novembre 10:30) [b]Fake news, théories du complot, images générées par IA… Jamais nous n''avons été aussi exposés à la désinformation. Mais qui la fabrique, comment se propage-t-elle et à qui profite-t-elle ?[b][b]À travers des exemples concrets, des enquêtes et des expériences interactives, la journaliste Aude Favre nous plonge dans les coulisses de la désinformation et nous donne des clés pour déjouer les manipulations, vérifier l''information et reprendre le pouvoir sur ce que nous croyons vrai.[b][b]Une conférence pour apprendre à douter intelligemment, sans finir par douter de tout ![b][b]Aude Favre est une journaliste d''investigation française engagée dans la lutte contre la désinformation. Depuis plus de quinze ans, elle',
