  'Manifestation en soutien au peuple Palestinien',
  '🔥 APPEL AU RASSEMBLEMENT 🔥 🗓 Chaque samedi 📍 15h Place Jean Jaurès à Tours ✊ Nous sommes aux côtés du peuple palestinien, pour sa souveraineté, son droit à l''autodétermination, sa terre, sa dignité. ❌ Stop au génocide ❌ Stop à la colonisation ❌ Stop à l''apartheid ❌ STOP À LA COMPLICITÉ DES ÉTATS Nous n''oublions pas. Nous ne pardonnons pas. Nous ne nous tairons pas. 📢 PAS DE PAIX SANS JUSTICE 📢 PAS DE JUSTICE SANS LIBERTÉ 📢 PAS DE SILENCE FACE AU GÉNOCIDE ✊️🇵🇸 PALESTINE LIBRE 🇵🇸',
