  'mf-11e-edition-des-journees-de-l-economie-autrement-nouvelles-menaces-nou-20261126-dijon',
  '11e édition des journées de l''économie autrement - nouvelles menaces, nouveaux combats',
  '11e édition des journées de l''économie autrement - nouvelles menaces, nouveaux combats[b][b]Lieux Multiples - DIJON - VOIR SUR SITE DE L''ÉVÈNEMENT (jeudi, 26 novembre 17:00) https://journeeseconomieautrement.fr/ [b][b] L''économie autrement, c''est maintenant ! Limites écologiques, affaiblissement des liens, nouvelles précarités, rapport dégradé au travail, sentiment de déclassement, tensions…, au fur et à mesure que nos sociétés semblent s''épuiser, le modèle économique qui les sous-tend doit être interrogé. Pourquoi changer de modèle économique, et comment le faire ? Insécurités alimentaires, intelligence artificielle, chocs climatiques, pertes de souveraineté, solitudes, populismes…, l''époque brasse de nombreuses menaces. Émergentes, accentuées ou ayant changé de visage, beaucoup apparaissent comme nouvelles aux yeux des citoyens partout dans le monde, qui affichent alors leurs doutes, l',
