  'b3a568f8-1aba-5778-8896-8b80ba6bff97',
  'mf-la-marche-a-suivre-20261127-paris',
  'La Marche A Suivre',
  'LA MARCHE A SUIVRE[b][b]Loiret - Partout (vendredi, 27 novembre 00:00) Ecouter le terrain, pour construire demain : https://www.youtube.com/shorts/ZlhKpyB5FHw Une marche à travers la France pour aller à la rencontre des citoyens, recueillir leurs constats, leurs idées et les solutions qu''ils souhaitent faire entendre. Partout, des personnes connaissent intimement leur territoire, leur métier, leur quotidien. Elles savent ce qui fonctionne, ce qui ne fonctionne plus, et souvent ce qu''il faudrait changer. Pourtant, leur parole arrive rarement jusqu''aux lieux où se prennent les décisions. Besoin de contributeuses et contributeurs, marcheuses et marcheurs, journalistes, bénévoles, de repas, d''hébergement, de salle....vous avez le choix !! Date à vérifier 27 nov ici https://www.facebook.com/p/Kyria-Gaya-100000929218921/ 29 nov ici https://lamarcheasuivre.net/',
