  'mf-soiree-unitaire-et-solidaire-avec-cuba-20261127-paris',
  'SOIREE unitaire et solidaire avec Cuba',
  'SOIREE unitaire et solidaire avec Cuba[b][b]SARAN sdf - salle des fêtes (vendredi, 27 novembre 18:00) Soirée unitaire et solidaires 1000 panneaux solaires pour Cuba Prises de parole Musique cubaine Mojitos Repas sur réservation francecuba45@gmail.com Si vous ne voulez ou pouvez pas venir, vous pouvez participer https://www.facebook.com/100087994047643/photos/929422576667535/ "Pour les particuliers : votre don ouvre droit à une réduction d''impôt de 75% (loi Coluche) de son montant, dans la limite de 2 000 € (vous versez 100€, vous récupérez 75€, votre don ne vous coûte que 25€) si vous êtes imposable. Au-delà, la réduction d''impôt est de 66%, dans la limite de 20% de votre revenu imposable, si vous êtes imposable toujours. L''excédent est reportable sur 5 ans." https://don.secourspopulaire.fr/defaut/~mon-don',
