  '44cd1e1d-e69d-589d-9392-740cec632cd1',
  'mf-mobilisation-antifasciste-contre-le-canon-francais-20261128-paris',
  'Mobilisation antifasciste contre le Canon Français',
  'Le 28 novembre aura lieu le banquet du Canon Français à Biarritz aux Halles d''Iraty. Dans un contexte de montée du fascisme, de l''autoritarisme, de la banalisation des idées réactionnaires et nationalistes, nous voulons rappeler que ces idées nauséabondes ne se répandent pas par magie. En effet, il existe des soutiens financiers, matériels (notamment Pierre-Edouard Stérin, milliardaire étant lui même à la tête d''un projet politique réactionnaire et fasciste) leur permettant d''imposer des sociétés autoritaires, liberticides et répressives. Nous pensons que les institutions actuelles et les différents partis nourrissent cette escalade autoritaire, et ce même s''ils se cachent derrière un antifascisme de façade, répondant lui même à des fins électorales. La montée du fascisme est une tendance globale. Ainsi, un antifascisme réel et conséquent ne peut reposer sur une glorification et idéalisa',
  'autre',
