  'Villeurbanne : Lyon Antifa Fest',
  'Nouvelle édition du Lyon Antifa Fest, festival militant contre les violences coloniales et policières, le racisme, le sexisme, la Igbtqiaphobie, l''islamophobie et l''antisémitisme, qui associe concerts et conférences en soutien aux luttes antifascistes. Pour les préventes, cliquez ici. Après (…) La Rayonne 7 Rue Henri Legay, 69100 Villeurbanne',
