) VALUES (
  '3cd89dfc-dec6-5556-8d70-c2c7b6d410d4',
  'ami-permanence-syndicale-cnt-94-20270101-paris',
  'Permanence syndicale CNT 94',
  'Travailleurs avec ou sans emploi de l''éducation, des transports, de l''industrie, du commerce ou des services. N''attendez pas d''être dos au mur ! Lorsqu''on regarde autour de soi, c''est tout le monde qui est concerné par des problèmes au travail (Conflit avec son patron, non respect du droit du travail, licenciement, harcèlement,…) Rester isolé n''est pas la solution. Nous rencontrer, discuter c''est déjà commencer à trouver des solutions. Permanence syndicale tous les vendredis de 17h30 a 19h (sauf pendant les vacances scolaires et les jours fériés) À la maison des syndicats, 27 Bd des alliés-94600 Choisy-Le-Roi, 1er étage salle CNT Sinon pour nous contacter : etpics94@cnt-f.org ou 06 74 17 60 34 Sur Internet : Union régionale parisienne des syndicats CNT 350',
  'droits',
  'Paris',
  '75001',
  'FR', 'Europe/Paris',
  'Paris',
