  '38462d92-1084-5767-b51a-91f2ba063751',
  'ami-permanence-du-c-a-t-collectif-anti-travail-20270103-paris',
  'Permanence du C.A.T., Collectif Anti Travail',
  'Permanence du C.A.T. - Collectif Anti Travail RENDONS-NOUS INEMPLOYABLES ! Pas d''entourloupe possible : malgré et contre toutes les utopies sociales-démocrates, tous les discours des partis de gauche et des syndicats, nous ne pensons pas qu''il puisse exister la moindre émancipation dans le travail, ni dans un quelconque mythique "plein emploi". Travailler, c''est sans cesse soumettre de son temps, de sa force et de sa vie à une forme aliénante, que l''on travaille pour une grande firme, pour un petit patron local ou à son propre compte, en intérim, pour une assoc'' ou en insertion. C''est aussi au prix de cette aliénation obligatoire que nous obtenons du chômage, du RSA, de l''AAH, en pointant à France Travail, en donnant peut-être 15 heures de notre temps, en vivant toujours sous cette même menace de devoir montrer à chaque instant qu''on peut faire des efforts et qu''on est, quoi qu''il en soi',
  'droits',
  'Paris',
  '75001',
  'FR', 'Europe/Paris',
  'Paris',
  48.859, 2.347, NULL,
  '2027-01-03T13:30:00Z'::timestamptz,
