  TRUE,
  NULL,
  'https://www.agendamilitant.org/Permanence-du-C-A-T-Collectif-Anti-Travail-8733.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
