  '95979d9f-ff2d-5123-a0c1-72a27878e683',
  'ami-reunion-de-la-coordination-contre-la-repression-et-les-violences-polic-20270105-paris',
  'Réunion de la coordination contre la répression et les violences policières Paris - IDF',
  'La coordination contre la répression et les violences policières s''est créée en 2016 au moment du mouvement contre la loi Travail. Cette coordination s''est donné pour but de combattre la répression systématique du gouvernement face aux mobilisations sociales (blocus, manifestations, occupations...). Aujourd''hui, la coordination soutient l''idée que c''est l''ensemble de la répression quotidienne qu''il faut combattre face à la multiplication des lois absurdes qui font tomber de plus en plus de comportements dans l''illégalité. Rdv tous les mardi soirs à 18h30 à la Bourse du Travail de Paris pour en discuter. – 22/09 salle Pelloutier – 29/09 et 06/10 salle Tollet – 13/10 salle Pelloutier – du 3/11 au 22/12 salle Pelloutier Tous les autres mardis : salle Francisco Ferrer 350',
  'social',
  'Paris',
  '75001',
  'FR', 'Europe/Paris',
