  is_demo, published_at, created_at, updated_at
) VALUES (
  'aecd4e82-6205-4b79-b9c9-fe307a4d9af1',
  'ami-rencontre-autour-du-livre-ce-pays-est-a-nous-tous-20261027-paris-29',
  'Rencontre autour du livre "Ce pays est à nous tous"',
  'Komla Elolo Djiakpo sera l''invité de la librairie le mardi 27 octobre à 19h30 pour discuter de l''ouvrage auquel il a contribué « Ce pays est à nous tous » aux éditions Burn-août. Il sera accompagné d''une membre de l''association Survie et la rencontre sera animée par Pierre Tenne. Présentation de l''ouvrage par la maison d''édition : En 2024, l''Assemblée nationale togolaise adopte, sans consulter les Togolais·es, une nouvelle constitution et décrète la Ve république. C''est une véritable dictature, celle de la dynastie Gnassingbé qui, depuis presque 60 ans, réprime les aspirations de ce peuple à vivre libre et dignement. Le coup d''État constitutionnel de 2024 permet à Faure Gnassingbé de garder le pouvoir au Togo. En 2025, le peuple togolais se soulève face à cette décision inique et s''insurge pour faire chuter le régime. Ce livre est à la fois un témoignage de ce soulèvement, de ces suites et un voeu pour l''avenir du Togo. Voir aussi Le Monte en l''air Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75020',
  'FR', 'Europe/Paris',
  'Le Monte en l’air 2',
  48.855942, 2.397757, NULL,
  '2026-10-27T18:30:00Z'::timestamptz,
  '2026-10-27T21:30:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Rencontre-autour-du-livre-Ce-pays-est-a-nous-tous.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
  id, slug, title, description, category, city_name, postal_code, country_code, timezone,
  location_name, latitude, longitude, location_reveal_at,
  start_at, end_at, end_is_estimated, organizer_name, source_url,
  source_verification_status, publication_status, event_status_override,
  is_demo, published_at, created_at, updated_at
) VALUES (
  '7888ab9a-6ad2-43dc-9ed0-ac07e55281a6',
  'ami-la-nature-nous-manque-t-elle-encore-conference-philosophique-de-paul-k-20261027-paris-204',
  'La nature nous manque-t-elle encore ? Conférence philosophique de Paul Klotz',
  'La sensibilité à la nature : le moyen inexploré de réussir la bifurcation écologique. Parmi toutes les anesthésies que nous avons décrites précédemment, c''est dans le rapport à la nature que l''appauvrissement est le plus lourd de conséquences. En quarante ans, la surface des espaces artificialisés a augmenté de 72%. La population d''oiseaux dans les espaces agricoles a diminué de 60%. Des générations entières grandissent sans expérience directe du vivant. Or, moins on expérimente la nature, moins on la préserve. Les travaux en psychologie environnementalement le montrent : faute de référence sensible, les atteintes à l''environnement deviennent tolérables. Chacun sous-estime la destruction qui se déroule sous ses yeux, parce que sa propre mémoire du vivant est déjà appauvrie. Les politiques environnementales échouent à créer l''adhésion parce qu''elles s''adressent à des individus dont le lien sensible à la nature a déjà été sectionné. Renouer avec la nature est une condition politique de la bifurcation. Réservation conseillée. Places limitées. Le bar est ouvert avant et après la rencontr Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75006',
  'FR', 'Europe/Paris',
  'Librairie Le Delta 1',
  48.882438, 2.348162, NULL,
  '2026-10-27T18:30:00Z'::timestamptz,
  '2026-10-27T21:30:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/La-nature-nous-manque-t-elle-encore-Conference-philosophique-de-Paul-Klotz.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
