) VALUES (
  'd5067c17-a215-4e76-96ef-d46d76724578',
  'ami-taf-a-la-recherche-du-proletariat-perdu-rencontre-avec-paul-martel-20261028-paris-254',
  'Taf, à la recherche du prolétariat perdu, rencontre avec Paul Martel',
  'Il n''y a pas que les bourgeois qui échappent au travail, certains prolétaires en ont même fait une devise : « Ne travaillez jamais ! » et c''est une toute autre aventure. Mais que se passe-t-il lorsque, après des années à fuir l''aliénation et l''exploitation par la marge, on se retrouve contraint de rejoindre la masse de ceux qui, chaque jour, sont contraints de trimer ? Chômeur à ses heures, ouvrier dès qu''il ne le peut plus, Paul Martel a enquêté. Comment survivre dans un monde où le capitalisme a, pour un temps, tout corrompu et désagrégé ? Le prolétariat diffus peut-il en soi redevenir une menace ? Quels contes et légendes nous faut-il écrire ou réviser pour encore vivre-et-lutter ? Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75006',
  'FR', 'Europe/Paris',
  'Librairie Le Delta 1',
  48.882438, 2.348162, NULL,
  '2026-10-28T18:00:00Z'::timestamptz,
  '2026-10-28T21:30:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Taf-a-la-recherche-du-proletariat-perdu-rencontre-avec-Paul-Martel.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
