) VALUES (
  '43117538-5e32-4028-9b78-0648da8c29da',
  'ami-lancement-de-la-bd-pause-croissance-avec-sophie-bourlet-20261029-paris-295',
  'Lancement de la BD « Pause croissance » avec Sophie Bourlet',
  'A l''occasion de la sortie de la BD « Pause croissance : A la recherche du bonheur intérieur brut », nous recevons Sophie Bourlet le jeudi 29 octobre à 19h. A la croisée du récit satirique et du traité d''économie, Sophie Bourlet et Nicola Gobbi signent une BD aussi savant qu''hilarante. Accompagnés par la sociologue Dominique Méda et l''économiste Timothée Parrique, ils explorent les utopies et alternatives concrètes. Sophie Bourlet est autrice et journaliste indépendante diplômée en économie, elle travaille notamment sur les questions d''inégalités et d''environnement pour différents médias, dont RFI, Mediapart et Alternatives Économiques. Voir aussi librairie Utopia Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75005',
  'FR', 'Europe/Paris',
  'Librairie Utopia 1 rue Frédéric Sauton',
  48.851277, 2.349331, NULL,
  '2026-10-29T18:00:00Z'::timestamptz,
  '2026-10-29T19:30:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Lancement-de-la-BD-Pause-croissance-avec-Sophie-Bourlet.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
  id, slug, title, description, category, city_name, postal_code, country_code, timezone,
  location_name, latitude, longitude, location_reveal_at,
