  source_verification_status, publication_status, event_status_override,
  is_demo, published_at, created_at, updated_at
) VALUES (
  '76e0211b-ddc4-4ddc-beac-44f2209c79e5',
  'ami-projection-du-film-maximum-tolerated-dose-20261029-paris-296',
  'Projection du film ‘Maximum Tolerated Dose’',
  'Rendez-vous le jeudi 29 octobre pour une projection du film "Maximum Tolerated Dose". Présentation du film (1h30, anglais sous-titré français) : Maximum Tolerated Dose traite de l''expérimentation animale en retraçant la vie et le parcours d''humains et de non-humains qui en ont fait l''expérience directe. Le film donne la parole à ceux qui ont tourné le dos à ces pratiques après y avoir participé, à ceux qui libèrent les animaux, à ceux qui en prennent soin dans leur foyer ou en sanctuaires. Comment en arrive-t-on à participer à ce système et même à le justifier ? Comment le quitter une fois qu''on s''y est engagé ? Quelles réparations possibles pour ses victimes, quelle autre vie peut-on leur offrir une fois sorties des laboratoires ? Le film contient des passages qui peuvent êtres difficiles - pas d''image gore à proprement parler, mais des descriptions et des images d''animaux en souffrance physique et psychologique. Suite à la projection, nous échangerons sur le sujet. L''entrée est à prix libre (gratuité comprise) et sans inscription. Sur place il y aura aussi un infokiosque et un bar  Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75019',
  'FR', 'Europe/Paris',
  'Le Baranoux 78 Rue Compans',
  48.87932, 2.392106, NULL,
  '2026-10-29T18:00:00Z'::timestamptz,
  '2026-10-29T21:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Projection-du-film-Maximum-Tolerated-Dose-8807.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
