  is_demo, published_at, created_at, updated_at
) VALUES (
  '794ccc55-40e2-49af-a028-49cc72dae20b',
  'ami-arpentage-du-livre-mondes-post-capitalistes-20261030-paris-334',
  'Arpentage du livre ‘Mondes post-capitalistes’',
  'Il est temps de rouvrir le futur et de faire mentir l''adage selon lequel il serait plus facile d''imaginer la fin du monde que la fin du capitalisme. Ce livre prend acte de l''échec catastrophique des projets dits "communistes" du XXe siècle comme des menaces pesant sur l''habitabilité de la terre et la survie des espèces. Ce faisant, il cherche à aller au-delà d''une critique du capitalisme restée impuissante et souvent éloignée des enjeux écologiques. Il étend, de ce fait, notre compréhension du capitalisme bien au-delà des questions économiques, qui ont considérablement restreint l''analyse et le débat. Le dépassement du capitalisme ne peut se concevoir sans une redéfinition de nos manières de vivre, de coexister, de nous relier aux autres vivants et de donner sens à nos existences. En s''intéressant aussi bien aux rêves qu''aux psychés postcapitalistes, aux matériaux qu''aux techniques, à la mort qu''aux religions, aux conflits et à la guerre qu''aux fêtes et aux rituels, à l''éducation qu''aux échelles d''organisation de la vie sociale, à l''amour qu''aux arts ou à la famille qu''aux genres ou  Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75006',
  'FR', 'Europe/Paris',
  'Librairie Le Delta 1',
  48.882438, 2.348162, NULL,
  '2026-10-30T18:00:00Z'::timestamptz,
  '2026-10-30T21:30:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Arpentage-du-livre-Mondes-post-capitalistes.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
