) VALUES (
  '7193a51b-5101-4b47-819a-fe257bc57bd7',
  'ami-rencontre-discussion-avec-nicolas-rouille-autour-du-sahara-occidental-20261103-librairie-envie-d',
  'Rencontre-discussion avec Nicolas Rouillé autour du Sahara occidental',
  'Venez échanger avec Nicolas Rouillé autour de son livre "Laâyoune, en attendant" (Anarchasis) dans une discussion autour des Sahraouis et de leur indépendance. Le livre : Daha, Maalouma, Otman et leurs camarades terminent l''année au lycée Tanmiya de Laâyoune, au Sahara occidental. L''humiliation infligée à l''un d''entre eux par un professeur marocain au prétexte de ses origines sahraouies les tire de leur torpeur et les renvoie brutalement à leur condition de colonisés. Au rythme des matchs de foot de la Coupe d''Afrique des nations, terrain d''affrontements géopolitiques, la petite bande d''amis prépare sa riposte. Déjouant l''ombre portée d''un passé qui voudrait les condamner à la résignation, la prison ou l''exil, ils cherchent leur route dans un temps suspendu, dans l''attente d''une lointaine indépendance. Source Agenda Militant Indépendant.',
  'autre',
  'Librairie Envie De Lire',
  '93200',
  'FR', 'Europe/Paris',
  'Librairie Envie de lire 16 Rue Gabriel Péri',
  48.931412, 2.356261, NULL,
  '2026-11-03T18:00:00Z'::timestamptz,
  '2026-11-03T21:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Rencontre-discussion-avec-Nicolas-Rouille-autour-du-Sahara-occidental.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
  id, slug, title, description, category, city_name, postal_code, country_code, timezone,
  location_name, latitude, longitude, location_reveal_at,
