  source_verification_status, publication_status, event_status_override,
  is_demo, published_at, created_at, updated_at
) VALUES (
  '221e43b3-960b-4e7e-a225-731a51d0d010',
  'ami-rencontre-avec-noemie-merleau-ponty-20261103-paris-446',
  'Rencontre avec Noémie Merleau-Ponty',
  'Depuis près d''un demi-siècle, la procréation médicalement assistée a permis la naissance de plus de 10 millions d''enfants. À l''heure où l''infertilité progresse et où les enjeux démographiques s''invitent dans le débat public, cette pratique ne relève pas seulement de la médecine : elle mêle les trajectoires les plus intimes avec des enjeux de société. À partir d''une enquête menée au sein d''une clinique de PMA, Noémie Merleau-Ponty retrace les parcours de patientes confrontées à l''attente, aux échecs ou à l''exil médical. En suivant chaque jour le travail de biologistes et techniciennes, de la ponction ovocytaire jusqu''au transfert embryonnaire, l''autrice dévoile les coulisses de l''aide aux personnes engagées dans un projet parental. Un récit vivant où ces lieux habituellement fermés au public apparaissent comme des espaces éminemment humains, habités par les espoirs de celles et ceux qui les traversent. Noémie Merleau-Ponty est anthropologue au CNRS, spécialiste de la reproduction, de l''infertilité, de la baisse de la natalité et de la bioéthique. Ses recherches, menées en France, en I Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75006',
  'FR', 'Europe/Paris',
  'Librairie Le Delta 1',
  48.882438, 2.348162, NULL,
  '2026-11-03T18:00:00Z'::timestamptz,
  '2026-11-03T21:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Rencontre-avec-Noemie-Merleau-Ponty.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
