) VALUES (
  '66392d04-f66a-4aaa-8e6a-e318214423f4',
  'ami-ia-et-production-robotique-pour-le-meilleur-ou-pour-le-pire-un-debat-p-20261104-paris-477',
  'IA et production robotique, pour le meilleur ou pour le pire ? Un débat proposé par Décroissance IDF',
  'Alors que les preuves s''accumulent sur l''impact massif de l''intelligence artificielle sur le marché du travail, le gouvernement, tout comme les partis dits d''opposition, continuent de regarder ailleurs. Cécité volontaire ? Une utilisation socialement bénéfique de l''IA productive est-elle concevable ? Sur le versant pessimiste, ne faut-il redouter l''avènement d''un techno-féodalisme ? Problématisation présentée par Alain Véronèse. Suivie par questions, contradictions débat. Une soirée info/débat proposée par Décroissance Idf. Voir sur OC Paris Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75012',
  'FR', 'Europe/Paris',
  'Maison de la vie associative et citoyenne 12e 181',
  48.838253, 2.40486, NULL,
