  '7aa47f43-e203-404a-ae5b-0b3f917f3029',
  'ami-gouverner-pour-dominer-autrui-par-luc-foisneau-20261104-paris-486',
  'Gouverner, pour dominer autrui ? Par Luc Foisneau',
  'Si l''État a cherché à utiliser à son service les techniques du gouvernement, il n''est pas vrai de dire que les arts de gouverner n''existent que pour l''État. On pourra s''interroger sur les multiples formes que ces arts ont pu prendre depuis les premiers traités de la raison d''État en Italie jusqu''aux algorithmes qui gouvernent aujourd''hui nos vies. N''y aurait-il pas un projet propre à ces arts de gouverner et à celles et ceux qui s''en prévalent ? Comment peut-on comprendre les politiques qui font de la domination sur autrui le but ultime des arts de gouverner. L''actualité nous donne maints exemples de cette pensée du gouvernement, mais il n''est pas vrai qu''elle est une invention récente. En partant de Machiavel, nous essaierons de nous repérer parmi les formes diverses qu''a pu prendre la pensée de la raison d''État. Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75006',
  'FR', 'Europe/Paris',
  'Librairie Le Delta 1',
  48.882438, 2.348162, NULL,
  '2026-11-04T18:30:00Z'::timestamptz,
  '2026-11-04T21:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Gouverner-pour-dominer-autrui-Par-Luc-Foisneau.html',
