) VALUES (
  '32da8e0b-c2fe-4029-abf2-9617c16511b2',
  'ami-cine-leon-projection-rencontre-20261106-paris-543',
  'Ciné Léon (projection-rencontre)',
  'Projection de "La FoRêT Est A NouS", un film documentaire d''Anne Faisandier Dans le cadre d''un Docu près de chez Vous, proposé par Addoc (l''Association des cinéastes documentaristes) Synopsis : « Que se passe-t-il en forêt morvandelle ? C''est quoi ces alignements de bois noirs, ces champs de RUINES... ? Je décide de mener l''enquête et, grâce à quatre militants, je découvre la LUTTE qui se joue ici pour la défense de la forêt. Tous différents, leur engagement s''enracine et se déploie, à la façon des ARBRES, comme quatre branches ou quatre racines de la lutte. Ils m''aident à comprendre. Je ne me rendais pas compte à quel point j''aimais la forêt : NOTRE FORÊT. » (Anne Faisandier) Suivi d''une rencontre en présence de la réalisatrice Anne Faisandier ... et de la traditionnelle auberge espagnole pour partager ensemble nos boissons et petits plats. Voir aussi Le Ciné Léon Voir aussi Centre Mercoeur Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75011',
  'FR', 'Europe/Paris',
  'MJC Mercoeur 5 Cité Souzy',
  48.851695, 2.388751, NULL,
  '2026-11-06T19:30:00Z'::timestamptz,
  '2026-11-06T22:30:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Cine-Leon-Projection-rencontre-8809.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
