  'ami-armer-la-non-violence-rencontre-avec-nathalie-achard-20261110-paris-636',
  'Armer la non-violence, Rencontre avec Nathalie Achard',
  'La non-violence traverse une crise de crédibilité : récupérée, figée en dogme, elle est souvent devenue un argument pour désarmer les luttes plutôt qu''un outil pour les mener. Activiste et formatrice, Nathalie Achard entend lui rendre sa puissance de transformation. Pour cela, elle regarde en face ses limites et les privilèges qu''elle suppose, et plaide pour une non-violence à la fois radicale et pragmatique : qui fait place à la colère, qui distingue se protéger et punir, et qui accepte le conflit sans le réduire à un jugement moral. Voir aussi : Librairie Le Delta Source Agenda Militant Indépendant.',
  'autre',
  'Paris',
  '75006',
  'FR', 'Europe/Paris',
