) VALUES (
  '29fee7f3-295b-4a34-be8e-d422e33fb20b',
  'ami-cinematec-projection-debat-de-la-resistance-a-la-resilience-20261210-centre-protestant-857',
  'CinémaTec. Projection-débat ‘De la résistance à la résilience’',
  'Dix ans après, Marie-Monique Robin et son équipe retournent à Ungersheim ! Ce film raconte le chemin parcouru depuis le rejet d''un projet « Pierre et Vacances », pourtant soutenu par tous les élus de la région, jusqu''à la reconnaissance de l''exemplarité du village, qui inspire aujourd''hui l''agglomération de Mulhouse et bien au-delà. – Autonomie énergétique (électricité, chauffage) – Autonomie alimentaire renforcée : régie agricole avec 4 maraîchers municipaux, épicerie solidaire dans un bâtiment à énergie positive – Un exemple remarquable de biodiversité grâce aux arbres et haies plantés – Aucune hausse d''impôts depuis 2003 ! Marie-Monique Robin, sera présente pour animer le débat et répondre à vos questions. Journaliste d''investigation, réalisatrice et écrivaine, Marie-Monique Robin est reconnue pour ses documentaires et enquêtes sur des sujets comme les dérives des multinationales (notamment Monsanto), les menaces sur la biodiversité, les pandémies et les alternatives écologiques. Elle a reçu plusieurs distinctions, dont le prix Albert-Londres en 1995 et le prix norvégien Rachel Ca Source Agenda Militant Indépendant.',
  'autre',
  'Centre Protestant',
  '71300',
  'FR', 'Europe/Paris',
  'Centre Protestant 36 rue Jean Longuet',
  46.671188, 4.371925, NULL,
  '2026-12-10T19:00:00Z'::timestamptz,
  '2026-12-10T22:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/CinemaTec-Projection-debat-De-la-resistance-a-la-resilience-8770.html',
