  '148e2970-8802-5319-8164-ffbc4d12374e',
  'ami-permanence-de-la-bibliotheque-associative-de-malakoff-20270102-paris',
  'Permanence de la Bibliothèque Associative de Malakoff',
  'N''hésitez pas à venir nous rencontrer, emprunter ou rendre des ouvrage, discuter... Voir aussi : Emprunter des livres Voir aussi : La BAM 350',
