);INSERT INTO events (
  id, slug, title, description, category, city_name, postal_code, country_code, timezone,
  location_name, latitude, longitude, location_reveal_at,
  start_at, end_at, end_is_estimated, organizer_name, source_url,
  source_verification_status, publication_status, event_status_override,
  is_demo, published_at, created_at, updated_at
) VALUES (
  'eb0e0167-2bf6-5119-a5de-2a1d3855bece',
  'ami-permanences-syndicales-cnt-region-parisienne-20270104-paris',
  'Permanences syndicales CNT région parisienne',
  'Le temps de longs et lourds travaux de rénovation du 33, rue des Vignoles, la CNT RP s''installe au 37 bis, rue des Trois Bornes dans le 11e (métro : Parmentier, Goncourt ou Couronnes). La CNT déménage mais la lutte continue ! Nos permanences sont ouvertes les : . lundis de 14h à 17h (interpro), . mercredis de 17h à 19h (éducation), . samedis de 10h à 12h (bâtiment). Venez nous rencontrer ; discuter, c''est déjà commencer à trouver des solutions aux problèmes rencontrés... N''hésitez pas à : . Prendre contact avec notre organisation, échanger sur nos pratiques et orientations, ceci quel que soit votre secteur professionnel. . Découvrir le service-librairie de la région et les dernières publications des Éditions CNT-RP ou d''autres maisons d''éditions. . Vous procurer des tracts, autocollants. . Obtenir des informations. . Rejoindre notre organisation. Contact : br.rp @ cnt-f.org Voir sur Face',
  'autre',
  'Paris',
  '75001',
  'FR', 'Europe/Paris',
  'Paris',
  48.859, 2.347, NULL,
  '2027-01-04T13:00:00Z'::timestamptz,
  '2027-01-04T16:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Permanences-syndicales-CNT-region-parisienne-5794.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
);INSERT INTO events (
  id, slug, title, description, category, city_name, postal_code, country_code, timezone,
  location_name, latitude, longitude, location_reveal_at,
  start_at, end_at, end_is_estimated, organizer_name, source_url,
  source_verification_status, publication_status, event_status_override,
  is_demo, published_at, created_at, updated_at
) VALUES (
  '120a3524-7699-544d-a50e-dc70c7eb76e3',
  'ami-cercle-de-femmes-20270107-paris',
  'Cercle de femmes',
  'Un cercle de parole réservé aux femmes. Les participantes choisissent les thèmes abordés, chacune peut déposer sa parole en toute liberté, sans chercher de conseils, d''approbation, sans être interrompue. Ces réunions sont des moments de soins et de sororité, qui permettent de casser les solitudes, sans la pression liée au militantisme. Tous les premiers jeudis du mois à La Trockette, Paris 11e, de 19h à 22h. Le cercle de femmes est gratuit, sur adhésion à l''association qui nous héberge. En venant, il faut simplement faire son adhésion au bar (entre 6EUR et 18EUR/an pour accéder à toutes leurs activités). Informations et inscriptions par texto : 07 68 61 09 01 Voir aussi la petite Rockette 350',
  'autre',
  'Paris',
  '75001',
  'FR', 'Europe/Paris',
  'Paris',
  48.859, 2.347, NULL,
  '2027-01-07T18:00:00Z'::timestamptz,
  '2027-01-07T21:00:00Z'::timestamptz,
  TRUE,
  NULL,
  'https://www.agendamilitant.org/Cercle-de-femmes.html',
  'source_provided', 'published', NULL,
  FALSE, now(), now(), now()
